// The image of a post (ADR 0016): generated by the worker for the cover and the close of a post
// whose look takes one, stored with the version. Pure types and rules; the worker does the I/O.

export const ART_SLOTS = ["cover", "cta"] as const;
export type ArtSlot = (typeof ART_SLOTS)[number];

export const ART_STATUSES = ["pending", "ready", "partial", "skipped", "failed"] as const;
/**
 * pending: waiting for the worker · ready: every slot has its image · partial: some slots do ·
 * skipped: no image on purpose (no credentials, the look takes none, the daily cap) · failed:
 * the provider could not make them (the post renders with the look's own art).
 */
export type ArtStatus = (typeof ART_STATUSES)[number];

export type ArtImage = {
  /** Relative to MEDIA_DIR: <brand>/<postId>/<versionId>/art/<slot>.jpg */
  path: string;
  /** The full prompt sent (the AI's subject plus the fixed rules). */
  prompt: string;
  model: string;
  createdAt: string;
};

export type PostArt = {
  status: ArtStatus;
  images: Partial<Record<ArtSlot, ArtImage>>;
  /** Why there are no (or not all) images, for the panel. */
  note?: string;
};

/** Images a day, at most: well under the free allocation (~100 a day, ADR 0016). */
export const ART_DAILY_CAP = 60;

/** Whether the render should wait for the images (it never waits for a finished state). */
export const isArtPending = (art: PostArt | null | undefined) => art?.status === "pending";
